package org.brightstats.data;
import java.util.*;
import java.nio.file.*;
import com.google.gson.*;
public final class PreferencesChecks {
    private static int checks;
    private static void require(boolean condition,String message){checks++;if(!condition)throw new AssertionError(message);}
    private static void reject(Runnable action){try{action.run();throw new AssertionError("Invalid preferences accepted");}catch(IllegalArgumentException expected){checks++;}}
    public static void main(String[] args)throws Exception{Path output=Path.of(args[0]);Files.createDirectories(output);Path file=output.resolve("preferences.json");var original=new UserPreferences(UserPreferences.Theme.DARK,UserPreferences.Language.FRENCH,"fr-FR",4,17,40,4,1000000);original.save(file);require(UserPreferences.load(file).preferences().equals(original),"Preferences round-trip");require(UserPreferences.load(file).warning().isEmpty(),"Valid file has no warning");byte[] before=Files.readAllBytes(file);reject(()->new UserPreferences(UserPreferences.Theme.LIGHT,UserPreferences.Language.ENGLISH,"unknown",6,13,100,8,5000000));reject(()->new UserPreferences(UserPreferences.Theme.LIGHT,UserPreferences.Language.ENGLISH,"en-US",13,13,100,8,5000000));reject(()->new UserPreferences(UserPreferences.Theme.LIGHT,UserPreferences.Language.ENGLISH,"en-US",6,50,100,8,5000000));reject(()->new UserPreferences(UserPreferences.Theme.LIGHT,UserPreferences.Language.ENGLISH,"en-US",6,13,10000,8,5000000));reject(()->new UserPreferences(UserPreferences.Theme.LIGHT,UserPreferences.Language.ENGLISH,"en-US",6,13,100,0,5000000));require(Arrays.equals(before,Files.readAllBytes(file)),"Invalid edits do not touch stored preferences");Path bad=output.resolve("unsupported.json");Files.writeString(bad,"{\"format\":\"bright-stats-preferences\",\"version\":9}");var loaded=UserPreferences.load(bad);require(loaded.preferences().equals(UserPreferences.defaults())&&!loaded.warning().isEmpty(),"Unsupported file falls back visibly");require(Files.readString(bad).contains("9"),"Unsupported file retained");Files.writeString(bad,"{\"format\":\"bright-stats-preferences\",\"version\":1,\"preferences\":null}");loaded=UserPreferences.load(bad);require(loaded.preferences().equals(UserPreferences.defaults())&&!loaded.warning().isEmpty(),"Null preferences fall back visibly");require(UserPreferences.load(output.resolve("absent.json")).preferences().equals(UserPreferences.defaults()),"First-run defaults");try(var files=Files.list(output)){require(files.noneMatch(path->path.getFileName().toString().endsWith(".tmp")),"No temporary preference files");}var receipt=new JsonObject();receipt.addProperty("checks",checks);receipt.add("stored",new Gson().toJsonTree(original));Files.writeString(output.resolve("core.json"),new GsonBuilder().setPrettyPrinting().create().toJson(receipt));System.out.println(new Gson().toJson(receipt));}
}
